SELECT merchant, CASE WHEN amount >= 3900 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, SUM(amount) FILTER (WHERE merchant = 'Amazon') AS amazon_total_amount, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN merchant = '7-Eleven' THEN 1 END), 0), 2) AS amount_per_7_eleven, MAX(amount) FILTER (WHERE merchant = '7-Eleven') AS 7_eleven_max_amount, ROUND(AVG(amount), 2) AS avg_amount FROM transactions GROUP BY merchant, CASE WHEN amount >= 3900 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY amazon_total_amount DESC NULLS LAST
